import type { BankQuestion } from "@/lib/bank";

/** Time and Work (Quantitative Aptitude): 142 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-time-work-1","question":"If A can do a piece of work in 8 days, the fraction of work A does in one day is:","options":["1/4","1/8","1/16","8"],"answer":1,"explanation":"One day’s work = 1 ÷ 8 = 1/8.","difficulty":"easy"},
  {"id":"quant-time-work-2","question":"If 6 workers finish a job in 12 days, how many days will 9 workers take at the same rate?","options":["6","8","9","18"],"answer":1,"explanation":"Work = 6 × 12 = 72 worker-days; 72 ÷ 9 = 8 days.","difficulty":"moderate"},
  {"id":"quant-time-work-3","question":"A is twice as efficient as B. If together they finish a job in 12 days, A alone would take:","options":["18 days","24 days","36 days","16 days"],"answer":0,"explanation":"Let B’s rate be 1 and A’s 2: together 3 units/day, total work 36 units; A alone = 36 ÷ 2 = 18 days.","difficulty":"very-hard"},
  {"id":"quant-time-work-4","question":"A can finish a work in 10 days and B in 15 days. Together they finish it in:","options":["5 days","6 days","8 days","12 days"],"answer":1,"explanation":"1/10 + 1/15 = 1/6 ⇒ 6 days.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-time-work-5","question":"A and B together finish a job in 12 days; A alone takes 20 days. B alone takes:","options":["24 days","30 days","32 days","40 days"],"answer":1,"explanation":"1/12 − 1/20 = 1/30 ⇒ 30 days.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-time-work-6","question":"A can do a work in 12 days. After working 4 days he leaves and B finishes the rest in 16 days. B alone would take:","options":["20 days","24 days","28 days","32 days"],"answer":1,"explanation":"A did 1/3; B did 2/3 in 16 days ⇒ full work in 24 days.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-time-work-7","question":"12 men complete a work in 18 days. After 6 days, 4 more men join. The remaining work is finished in:","options":["8 days","9 days","10 days","12 days"],"answer":1,"explanation":"Remaining = 12 × 12 = 144 man-days; 16 men ⇒ 9 days.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-8","question":"A does one-third of a work in 6 days. He will finish the whole work in:","options":["9 days","24 days","12 days","18 days"],"answer":3,"explanation":"One-third in 6 days means the whole in 3 × 6 = 18 days.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-time-work-9","question":"One pipe fills a tank in 6 hours and another in 12 hours. Together they fill it in:","options":["4 hours","8 hours","9 hours","3 hours"],"answer":0,"explanation":"Combined rate = 1/6 + 1/12 = 3/12 = 1/4 of the tank per hour, so 4 hours. Averaging 6 and 12 to get 9 is wrong.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-10","question":"A and B can do a work in 12 days, B and C in 15 days, and C and A in 20 days. All three together will finish it in:","options":["15 days","20 days","5 days","10 days"],"answer":3,"explanation":"Adding: 2(A + B + C) = 1/12 + 1/15 + 1/20 = (5 + 4 + 3)/60 = 12/60, so A + B + C = 6/60 = 1/10 per day: 10 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-11","question":"A can do a work in 20 days and B in 30 days. They begin together, but A leaves 5 days before the work is completed. The work is completed in:","options":["12 days","17 days","15 days","10 days"],"answer":2,"explanation":"Let the work take t days: B works all t days, A works t − 5. (t − 5)/20 + t/30 = 1 → 3(t − 5) + 2t = 60 → 5t = 75 → t = 15 days.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-time-work-12","question":"10 men or 15 women can do a work in 12 days. In how many days will 8 men and 6 women finish it?","options":["9 days","8 days","12 days","10 days"],"answer":3,"explanation":"1 man = 1.5 women, so 8 men + 6 women = 12 + 6 = 18 women. 15 women take 12 days, so 18 women take 15 × 12/18 = 10 days.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-time-work-13","question":"A pipe can fill a tank in 8 hours and a drain can empty it in 12 hours. If both are open, the empty tank fills in:","options":["16 hours","20 hours","24 hours","4.8 hours"],"answer":2,"explanation":"Net rate = 1/8 − 1/12 = 1/24 per hour, so 24 hours. 4.8 h is the slip of adding the rates.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-14","question":"A is 50% more efficient than B. If B alone can do a work in 15 days, A and B together will do it in:","options":["6 days","7.5 days","9 days","5 days"],"answer":0,"explanation":"A takes 15/1.5 = 10 days. Together: 1/10 + 1/15 = 1/6, so 6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-15","question":"Two pipes fill a tank in 12 hours and 16 hours. Both are opened together, and after 4 hours the first pipe is closed. The remaining part is filled by the second pipe in:","options":["7 hours","6 hours 40 minutes","6 hours","5 hours 20 minutes"],"answer":1,"explanation":"In 4 hours both fill 4(1/12 + 1/16) = 4 × 7/48 = 7/12. The remaining 5/12 at 1/16 per hour takes 5/12 × 16 = 20/3 hours = 6 h 40 min.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-time-work-16","question":"A, B and C can do a work in 24, 30 and 40 days respectively. They start together, but C leaves 4 days and B leaves 6 days before the work is finished. The work is finished in:","options":["11 days","13 days","12 days","15 days"],"answer":1,"explanation":"Take the work as 120 units: rates 5, 4, 3 per day. If it takes T days, 5T + 4(T − 6) + 3(T − 4) = 120 → 12T − 36 = 120 → T = 13 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-17","question":"A can do a work in 12 days and B in 18 days. They work on alternate days with A starting. The work is completed in:","options":["14½ days","15 days","14⅓ days","14 days"],"answer":2,"explanation":"Work = 36 units: A does 3, B does 2 per day, 5 units per 2-day cycle. 7 cycles (14 days) do 35 units; the last unit is done by A on day 15 in 1/3 day. Total 14⅓ days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-18","question":"A, B and C can do a work alone in 6, 8 and 12 days respectively. Working together they are paid ₹2,700. B's share is:","options":["₹600","₹900","₹1,000","₹1,200"],"answer":1,"explanation":"Wages are shared in the ratio of work done, i.e. of rates: 1/6 : 1/8 : 1/12 = 4 : 3 : 2. B gets 3/9 × 2,700 = ₹900.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-time-work-19","question":"Pipe A fills a tank in 6 hours and pipe B in 8 hours. They are opened for one hour each alternately, A first. The tank is filled in:","options":["6 hours 45 minutes","6 hours 30 minutes","6 hours 51 minutes","7 hours"],"answer":0,"explanation":"Tank = 24 units: A gives 4 per hour, B gives 3, so 7 units per 2-hour cycle. After 3 cycles (6 h) 21 units are in; A fills the last 3 units in 3/4 hour. Total 6 h 45 min. 6 h 51 min comes from wrongly averaging the rates.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-20","question":"12 men and 16 boys can do a work in 5 days; 13 men and 24 boys can do it in 4 days. The ratio of the daily work of a man to that of a boy is:","options":["2 : 1","1 : 2","3 : 1","3 : 2"],"answer":0,"explanation":"Total work: 5(12m + 16b) = 4(13m + 24b) → 60m + 80b = 52m + 96b → 8m = 16b → m : b = 2 : 1.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-21","question":"A is twice as efficient as B, and B is thrice as efficient as C. Together they finish a work in 10 days. C alone would take:","options":["30 days","60 days","90 days","100 days"],"answer":3,"explanation":"Rates A : B : C = 6 : 3 : 1, total 10 units a day, so the work = 100 units. C alone at 1 unit a day takes 100 days.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-time-work-22","question":"A certain number of workers can finish a job in 30 days. If there were 10 workers fewer, it would take 10 days more. The number of workers is:","options":["50","40","20","30"],"answer":1,"explanation":"Man-days are equal: 30N = 40(N − 10) → 30N = 40N − 400 → N = 40.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-time-work-23","question":"A contractor undertakes to build a road in 40 days with 50 men. After 20 days he finds that only one-third of the road is built. How many more men must he employ to finish on time?","options":["75","50","100","25"],"answer":1,"explanation":"50 × 20 = 1,000 man-days did one-third, so the whole road needs 3,000 man-days. The remaining 2,000 man-days in 20 days need 100 men, i.e. 50 more.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-time-work-24","question":"Two inlet pipes fill a tank in 10 and 15 hours and an outlet empties it in 12 hours. All three are opened on an empty tank; after 4 hours the outlet is closed. The tank is full after a total of:","options":["8 hours","10 hours","6 hours","12 hours"],"answer":0,"explanation":"Tank = 60 units: rates +6, +4, −5, net 5 per hour. In 4 hours 20 units are in. The remaining 40 at 10 per hour take 4 hours. Total 8 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-25","question":"How many of the following statements are correct?\n1. If A is twice as efficient as B, A takes half the time B takes.\n2. If 2 men do as much as 3 women, then 4 men and 3 women equal 9 women.\n3. If A does a work in 10 days and B in 15 days, together they take 6 days.\n4. A pipe fills a tank in 4 hours and a drain empties it in 6 hours; with both open the tank fills in 10 hours.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1 is true. 2 is true (4 men = 6 women; 6 + 3 = 9). 3 is true (1/10 + 1/15 = 1/6). 4 is false: 1/4 − 1/6 = 1/12, so 12 hours. Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-time-work-26","question":"A and B undertake to do a work for ₹1,200. A alone can do it in 6 days and B alone in 8 days. With the help of C they finish it in 3 days. C's share is:","options":["₹100","₹200","₹180","₹150"],"answer":3,"explanation":"In 3 days A and B do 3(1/6 + 1/8) = 7/8 of the work, so C did 1/8 and gets 1/8 × 1,200 = ₹150.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-27","question":"A and B together can do a work in 12 days, and B and C together in 16 days. A worked for 5 days, B for 7 days and C finished the remaining work in 13 days. C alone can do the work in:","options":["16 days","48 days","24 days","32 days"],"answer":2,"explanation":"Work = 48 units: A + B = 4 per day, B + C = 3 per day. 5A + 7B + 13C = 5(A + B) + 2(B + C) + 11C = 20 + 6 + 11C = 48 → C = 2 units a day → 24 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-28", "question": "A can finish a work in 20 days and B in 30 days. In how many days can they finish it together?", "options": ["25 days", "12 days", "10 days", "15 days"], "answer": 1, "explanation": "One day's work = 1/20 + 1/30 = 5/60 = 1/12, so 12 days. 25 days is the average of the times, a common slip.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-time-work-29", "question": "15 men working 8 hours a day build a wall in 24 days. How many days will 20 men working 9 hours a day take to build the same wall?", "options": ["16 days", "18 days", "20 days", "14 days"], "answer": 0, "explanation": "Work = 15 × 24 × 8 = 2,880 man-hours = 20 × 9 × d, so d = 16 days.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-time-work-30", "question": "A pipe fills a tank in 10 hours, but because of a leak it takes 12 hours. In how many hours can the leak empty the full tank?", "options": ["22 hours", "2 hours", "120 hours", "60 hours"], "answer": 3, "explanation": "Leak rate = 1/10 − 1/12 = 1/60 of the tank per hour, so it empties the tank in 60 hours.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-time-work-31", "question": "A is three times as efficient as B and finishes a job 40 days sooner than B. In how many days can they finish it together?", "options": ["20 days", "30 days", "15 days", "10 days"], "answer": 2, "explanation": "If A takes t days, B takes 3t, so 3t − t = 40 → t = 20; B takes 60. Together 1/20 + 1/60 = 4/60 → 15 days.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-32", "question": "A can do a work in 18 days and B in 24 days. They start together, but A leaves after 6 days. In how many more days will B finish the remaining work?", "options": ["12 days", "10 days", "14 days", "8 days"], "answer": 1, "explanation": "In 6 days together they do 6(1/18 + 1/24) = 6 × 7/72 = 7/12. The remaining 5/12 takes B (5/12) × 24 = 10 days.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-time-work-33", "question": "1 man and 2 women can finish a work in 10 days, while 2 men and 1 woman can finish it in 8 days. In how many days can 1 man alone finish it?", "options": ["20 days", "40 days", "30 days", "24 days"], "answer": 0, "explanation": "10(m + 2w) = 8(2m + w) → 10m + 20w = 16m + 8w → m = 2w. Then 10(2w + 2w) = 1 → w = 1/40, m = 1/20, so 20 days. 40 days is a woman's time.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-34", "question": "Pipes A and B fill a tank in 20 and 30 minutes, and pipe C empties it in 15 minutes. All three are opened on an empty tank at 10:00 am and C is closed at 10:10 am. When will the tank be full?", "options": ["10:22 am", "10:16 am", "10:30 am", "10:20 am"], "answer": 3, "explanation": "With all three, rate = 1/20 + 1/30 − 1/15 = (3 + 2 − 4)/60 = 1/60 per minute; in 10 min they fill 1/6. The remaining 5/6 at A + B's rate 1/12 per minute takes 10 min. Full at 10:20 am.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-35", "question": "A does 1/4 of a work in 5 days and B does 1/3 of it in 10 days. C is twice as efficient as B. In how many days will A, B and C together finish the work?", "options": ["7½ days", "5 days", "6⅔ days", "8 days"], "answer": 2, "explanation": "A alone: 20 days; B alone: 30 days; C (twice B) 15 days. Together 1/20 + 1/30 + 1/15 = (3 + 2 + 4)/60 = 9/60, so 60/9 = 6⅔ days.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-36", "question": "A job needs 100 worker-days of work. 20 workers start it, and at the end of each day 2 workers leave. In how many days is the job completed?", "options": ["5 days", "7⅓ days", "7 days", "8 days"], "answer": 1, "explanation": "Work done each day: 20, 18, 16, 14, 12, 10, 8 → total 98 after 7 days. On day 8 only 6 workers remain and 2 worker-days are left, which takes 2/6 = 1/3 day. Total 7⅓ days. 5 days assumes no one leaves.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-37", "question": "A is 20% more efficient than B, and B is 25% more efficient than C. Together the three finish a work in 12 days. In how many days can A and C together finish it?", "options": ["18 days", "20 days", "15 days", "24 days"], "answer": 0, "explanation": "Take C's efficiency = 4, then B = 5 and A = 6. Total work = (6 + 5 + 4) × 12 = 180 units. A + C = 10 units/day, so 18 days.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-time-work-38", "question": "A pipe fills a tank in 5 hours. What part of the tank does it fill in 2 hours?", "options": ["1/5", "5/2", "2/5", "3/5"], "answer": 2, "explanation": "In 1 hour it fills 1/5, so in 2 hours it fills 2/5.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-time-work-39", "question": "If 4 men can paint a house in 6 days, in how many days can 3 men paint it at the same rate?", "options": ["9 days", "7 days", "8 days", "4.5 days"], "answer": 2, "explanation": "Work = 4 × 6 = 24 man-days, so 3 men need 24/3 = 8 days. 4.5 days wrongly assumes fewer men work faster.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-time-work-40", "question": "A can do a piece of work in 15 days. What percent of the work does he complete in 6 days?", "options": ["45%", "40%", "36%", "60%"], "answer": 1, "explanation": "Each day he does 1/15 of the work, so in 6 days he does 6/15 = 2/5 = 40%.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-time-work-41", "question": "A and B can do a work in 18 days, B and C in 24 days, and A, B and C together in 12 days. In how many days can B alone do it?", "options": ["60 days", "36 days", "48 days", "72 days"], "answer": 3, "explanation": "C = 1/12 − 1/18 = 1/36 and A = 1/12 − 1/24 = 1/24, so B = 1/18 − 1/24 = 1/72: B takes 72 days.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-42", "question": "A is 40% less efficient than B. If B can finish a work in 12 days, how long will A take?", "options": ["16 days", "16.8 days", "20 days", "18 days"], "answer": 2, "explanation": "A's efficiency = 0.6 of B's, so A takes 12/0.6 = 20 days. Adding 40% to 12 days (16.8) treats time as directly proportional to the efficiency gap.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-43", "question": "12 men working 8 hours a day complete one-third of a work in 10 days. How many men working 10 hours a day are needed to finish the rest of the work in 8 days?", "options": ["18", "24", "20", "30"], "answer": 1, "explanation": "M₁D₁H₁/W₁ = M₂D₂H₂/W₂: (12 × 10 × 8)/(1/3) = (M × 8 × 10)/(2/3), so 2,880 = 120M and M = 24. Forgetting that 2/3 of the work remains gives 12.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-44", "question": "Pipes A and B fill a tank in 6 hours and 8 hours. When pipe C is also opened, the empty tank fills in 6 hours. In how many hours can C alone empty the full tank?", "options": ["6 hours", "12 hours", "24 hours", "8 hours"], "answer": 3, "explanation": "1/6 + 1/8 − 1/c = 1/6, so 1/c = 1/8 and C empties the tank in 8 hours: it exactly cancels pipe B.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-45", "question": "A and B together can do a work in 10 days. They work together for 4 days, after which A leaves and B finishes the rest in 9 days. In how many days can A alone do the work?", "options": ["15 days", "20 days", "30 days", "25 days"], "answer": 2, "explanation": "In 4 days they do 4/10 = 2/5, so B does 3/5 in 9 days and alone takes 15 days. A = 1/10 − 1/15 = 1/30, i.e. 30 days. 15 days is B's time.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-46", "question": "2 men can do as much work as 3 women or 4 children. If 6 men can do a work in 12 days, how long will 6 women and 8 children take to do it?", "options": ["8 days", "10 days", "12 days", "9 days"], "answer": 3, "explanation": "1 woman = 2/3 man and 1 child = 1/2 man, so 6 women + 8 children = 4 + 4 = 8 men. Time = 72 man-days ÷ 8 = 9 days.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-47", "question": "A completes 60% of a work in 15 days and then asks B to join him. Together they finish the rest in 4 days. In how many days can B alone do the whole work?", "options": ["25 days", "20 days", "16 2/3 days", "15 days"], "answer": 2, "explanation": "A does 4% a day. The remaining 40% in 4 days means 10% a day together, so B does 6% a day and needs 100/6 = 16 2/3 days.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-48", "question": "A job is started with 1 worker on day 1; on each later day one more worker joins (2 on day 2, 3 on day 3, and so on). One worker alone would take 55 days. In how many days is the job finished?", "options": ["10 days", "9 days", "11 days", "28 days"], "answer": 0, "explanation": "Worker-days after n days = 1 + 2 + … + n = n(n + 1)/2 = 55, so n = 10.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-time-work-49", "question": "A and B undertake a work for ₹7,200. A alone could do it in 12 days and B alone in 18 days. They work together for 4 days, then A leaves and B finishes the work. What is A's share of the money?", "options": ["₹2,400", "₹2,880", "₹4,320", "₹3,600"], "answer": 0, "explanation": "A worked 4 days and did 4/12 = 1/3 of the work, so he gets 1/3 × 7,200 = ₹2,400. Splitting in the efficiency ratio 3 : 2 (₹4,320) ignores that B worked longer.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-50", "question": "Pipes A and B fill a tank in 30 minutes and 45 minutes. Both are opened together. After how many minutes should B be closed so that the tank is full in exactly 24 minutes?", "options": ["15 minutes", "9 minutes", "12 minutes", "6 minutes"], "answer": 1, "explanation": "A runs all 24 minutes and fills 24/30 = 4/5. B must fill 1/5, which takes 45/5 = 9 minutes.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-51", "question": "A can finish a work in 20 working days. He works every day except Sunday and starts on a Monday. On which calendar day from the start does he finish?", "options": ["22nd day", "20th day", "24th day", "23rd day"], "answer": 3, "explanation": "Each week gives 6 working days: after 3 weeks (21 calendar days) he has done 18 days' work. Day 22 (Monday) and day 23 (Tuesday) complete the 20 days.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-time-work-52", "question": "A takes 6 days more than B to do a work, and together they finish it in 4 days. How long does A alone take?", "options": ["12 days", "8 days", "10 days", "6 days"], "answer": 0, "explanation": "If B takes x days: 1/x + 1/(x + 6) = 1/4 gives x² − 2x − 24 = 0, so x = 6 and A takes 12 days. Check: 1/6 + 1/12 = 1/4.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-53", "question": "A can do a work in 30 days, B in 20 days and C in 12 days. A starts alone; after 5 days B joins him, and after another 3 days C joins them. In how many days in all is the work finished?", "options": ["12 days", "11.5 days", "10.5 days", "11 days"], "answer": 1, "explanation": "A's 5 days: 1/6. Next 3 days (A + B = 1/12 a day): 1/4. Done = 5/12. The rest, 7/12, at A + B + C = 1/6 a day takes 3.5 days. Total = 5 + 3 + 3.5 = 11.5 days.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-54", "question": "A certain number of men can finish a work in some days. With 4 fewer men it takes 6 days more, and with 6 more men it takes 6 days less. How many men are there?", "options": ["20", "18", "24", "30"], "answer": 2, "explanation": "md = (m − 4)(d + 6) gives 6m − 4d = 24, and md = (m + 6)(d − 6) gives d = m + 6. So 6m − 4m − 24 = 24 and m = 24 (d = 30). Check: 24 × 30 = 20 × 36 = 30 × 24 = 720.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-time-work-55", "question": "A pipe fills 40% of a tank in 6 hours, and a drain empties 25% of it in 5 hours. If both are opened when the tank is half full, how long will it take to fill the tank?", "options": ["60 hours", "20 hours", "15 hours", "30 hours"], "answer": 3, "explanation": "Fill rate = 0.4/6 = 1/15 per hour; drain rate = 0.25/5 = 1/20. Net = 1/60 per hour, so the remaining half takes 30 hours. 60 hours is for an empty tank.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-time-work-56", "question": "How many of the following statements are correct?\n1. If A does a job in x days and B in y days, together they take xy/(x + y) days.\n2. If 10 men take 12 days for a job, 15 men take 8 days.\n3. If a pipe fills a tank in 4 hours and another empties it in 6 hours, together they fill the empty tank in 10 hours.\n4. If A is 50% more efficient than B, A takes 2/3 of B's time.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "1, 2 and 4 are true (120 man-days ÷ 15 = 8; time ∝ 1/efficiency = 1/1.5). 3 is false: 1/4 − 1/6 = 1/12, so it takes 12 hours.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-time-work-57", "question": "A can do a work in 30 days. He works alone for 10 days, after which B joins him and they finish the rest in 16 days. If instead B had worked alone for the first 10 days and A had then joined him, how many days in all would the work have taken?", "options": ["32 days", "26 days", "28 days", "30 days"], "answer": 0, "explanation": "A's 10 days = 1/3, so A + B do 2/3 in 16 days: A + B = 1/24 and B = 1/24 − 1/30 = 1/120. B's 10 days = 1/12; the remaining 11/12 at 1/24 a day takes 22 days. Total = 32 days.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-58", "question": "A, B and C can do a work in 10, 15 and 30 days respectively. A works every day, while B and C assist him on alternate days, B on the first day. In how many days is the work finished?", "options": ["7 days", "6 days", "6 1/2 days", "6 3/5 days"], "answer": 3, "explanation": "Day 1 (A + B) = 1/6; day 2 (A + C) = 2/15; two days = 3/10. After 6 days, 9/10 is done. On day 7, A + B do 1/6 a day, so the last 1/10 takes 3/5 of a day: 6 3/5 days.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-59", "question": "3 men or 5 women can finish a work in 30 days. A man is paid ₹500 a day and a woman ₹280 a day. Is it cheaper to get the job done by men only or by women only, and by how much?", "options": ["Women only, by ₹3,000", "Women only, by ₹6,000", "Both cost the same", "Men only, by ₹3,000"], "answer": 0, "explanation": "Men: 90 man-days × ₹500 = ₹45,000. Women: 150 woman-days × ₹280 = ₹42,000. Women are cheaper by ₹3,000 whatever the number hired, since the total wage depends only on person-days.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-60", "question": "A can do a work in 8 days working 9 hours a day, and B can do it in 12 days working 6 hours a day. If they work together 8 hours a day, in how many days will they finish it?", "options": ["4 days", "4.5 days", "5 days", "4.8 days"], "answer": 1, "explanation": "A needs 72 hours and B needs 72 hours, so together they need 36 hours, i.e. 36/8 = 4.5 days. Combining day-rates (1/8 + 1/12 → 4.8 days) ignores the different working hours.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-61", "question": "Pipe A fills a tank in 6 hours, pipe B in 8 hours, and pipe C empties it in 12 hours. They are opened one at a time for an hour each in the order A, B, C, A, B, C, … starting with an empty tank. When is the tank full?", "options": ["After 14 hours", "After 13 hours", "After 12 hours", "After 13.5 hours"], "answer": 1, "explanation": "Each 3-hour cycle adds 1/6 + 1/8 − 1/12 = 5/24. After 4 cycles (12 hours) the tank is 20/24 full (it never fills mid-cycle, since the most it reaches is 22/24). In the 13th hour A adds 4/24 and fills it exactly.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-62", "question": "Assertion (A): If 6 men can do a job in 10 days, 10 men can do it in 6 days.\nReason (R): For a fixed amount of work, the number of men and the number of days are inversely proportional.", "options": ["Both A and R are true, and R is the correct explanation of A", "A is false but R is true", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false"], "answer": 0, "explanation": "The job needs 60 man-days, so 10 men take 6 days (A); this follows from the inverse proportion in R.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-time-work-63", "question": "A pipe fills a tank in 3 hours, but because of a leak at the bottom it takes 30 minutes longer. If the tank is full and the pipe is closed, how long will the leak take to empty half the tank?", "options": ["21 hours", "3.5 hours", "10.5 hours", "7 hours"], "answer": 2, "explanation": "Leak rate = 1/3 − 1/3.5 = 1/3 − 2/7 = 1/21 per hour, so it empties the full tank in 21 hours and half of it in 10.5 hours.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-time-work-64", "question": "A and B together can do a work in 30 days. They work together for 20 days, then B leaves and A finishes the rest in 15 days. If A had left instead of B after the 20 days, how long would B have taken to finish the rest?", "options": ["30 days", "20 days", "45 days", "15 days"], "answer": 0, "explanation": "In 20 days they do 2/3, so A does 1/3 in 15 days: A = 1/45. B = 1/30 − 1/45 = 1/90, so B needs 1/3 × 90 = 30 days for the rest.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-65", "question": "A, B and C can do a work in 8, 12 and 16 days respectively. They work one at a time on successive days in the order A, B, C, A, B, C, … In how many days is the work finished?", "options": ["10 3/4 days", "11 1/4 days", "10 1/2 days", "11 days"], "answer": 0, "explanation": "One 3-day cycle does 1/8 + 1/12 + 1/16 = 13/48. After 9 days: 39/48. Day 10 (A): 45/48. On day 11, B (4/48 a day) needs 3/48, i.e. 3/4 of a day: 10 3/4 days.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-66", "question": "A, B and C are paid ₹6,800 in all for a job. A worked 6 days, B 8 days and C 10 days, and their daily rates of work are in the ratio 4 : 3 : 2. If pay is in proportion to the work done, what is C's share?", "options": ["₹1,600", "₹2,000", "₹2,267", "₹2,833"], "answer": 1, "explanation": "Work done ∝ 6 × 4 : 8 × 3 : 10 × 2 = 24 : 24 : 20, so C gets 20/68 × 6,800 = ₹2,000. Sharing by days alone (10/24) gives ₹2,833.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-time-work-67", "question": "Pipes A and B can fill a tank in 20 hours and 30 hours. A is opened at 6:00 am and B at 8:00 am. At what time is the tank full?", "options": ["6:00 pm", "7:00 pm", "6:30 pm", "6:48 pm"], "answer": 3, "explanation": "By 8 am A fills 2/20 = 1/10. Together they fill 1/20 + 1/30 = 1/12 per hour, so 9/10 takes 10.8 hours = 10 h 48 min after 8 am, i.e. 6:48 pm.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id":"quant-time-work-68","question":"A can finish a job in 24 days and B in 40 days. How long will they take working together?","options":["15 days","32 days","16 days","12 days"],"answer":0,"explanation":"Take the work as LCM 120 units: A does 5 a day and B 3, so 8 a day together. 120 ÷ 8 = 15 days.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-69","question":"8 identical taps fill a tank in 27 minutes. How long will 6 such taps take?","options":["20.25 minutes","32 minutes","30 minutes","36 minutes"],"answer":3,"explanation":"Tap-minutes are fixed: 8 × 27 = 216. With 6 taps, 216 ÷ 6 = 36 minutes.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-time-work-70","question":"A does 1/12 of a job in a day and B does 1/18. What fraction of the job do they finish together in 3 days?","options":["1/2","5/36","5/12","7/12"],"answer":2,"explanation":"Together per day: 1/12 + 1/18 = 5/36. In 3 days: 15/36 = 5/12.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-71","question":"36 workers can finish a job in 15 days. How many workers are needed to finish it in 12 days?","options":["29","45","40","48"],"answer":1,"explanation":"Worker-days = 36 × 15 = 540. In 12 days: 540 ÷ 12 = 45 workers.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-time-work-72","question":"One machine prints 1,200 pages in 8 minutes and another prints 1,200 pages in 12 minutes. How long will both take together to print 1,200 pages?","options":["10 minutes","4.8 minutes","5 minutes","4 minutes"],"answer":1,"explanation":"Together: 1,200/8 + 1,200/12 = 150 + 100 = 250 pages a minute. 1,200 ÷ 250 = 4.8 minutes.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-73","question":"The efficiencies of A and B are in the ratio 3 : 2. If B takes 30 days to finish a job, how long will A take?","options":["20 days","45 days","25 days","18 days"],"answer":0,"explanation":"Time is inversely proportional to efficiency: A's time = 30 × 2/3 = 20 days.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-time-work-74","question":"A completes 25% of a job in 5 days and B completes 20% of it in 6 days. How long will they take to finish the job together?","options":["11 days","25 days","15 days","12 days"],"answer":3,"explanation":"A alone = 20 days, B alone = 30 days. Together: 20 × 30/50 = 12 days.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-75","question":"A, B and C can do a job alone in 12, 16 and 24 days. How long will they take working together?","options":["6 days","52/3 days","16/3 days","5 days"],"answer":2,"explanation":"Work = 48 units: A 4, B 3, C 2 per day, total 9. Time = 48/9 = 16/3 days (5⅓ days).","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-76","question":"A and B together can do a job in 8 days, and A alone in 12 days. B works alone for 3 days and then A finishes the rest. How many days does the job take in all?","options":["12 days","10.5 days","13.5 days","15 days"],"answer":2,"explanation":"B alone = 24 days. In 3 days B does 1/8; A needs 7/8 × 12 = 10.5 days. Total = 13.5 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-77","question":"4 men or 6 women can do a job in 15 days. How long will 2 men and 3 women take?","options":["7.5 days","15 days","30 days","12 days"],"answer":1,"explanation":"4 men = 6 women, so 2 men = 3 women. Then 2 men + 3 women = 6 women, who take 15 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-78","question":"If 5 painters paint 5 rooms in 5 days, how many days will 10 painters take to paint 10 rooms?","options":["5 days","10 days","2.5 days","20 days"],"answer":0,"explanation":"One painter paints one room in 5 days. 10 painters paint 10 rooms in parallel, still 5 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-79","question":"A does 40% of a job in 8 days, and B finishes the remaining work in 6 days. How long would they take to do the whole job together?","options":["7 days","14 days","6 days","20/3 days"],"answer":3,"explanation":"A alone = 20 days. B does 60% in 6 days, so B alone = 10 days. Together: 20 × 10/30 = 20/3 days (6⅔).","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-80","question":"Working 6 hours a day, a man finishes a job in 10 days. In how many days will he finish it working 7.5 hours a day?","options":["12.5 days","7.5 days","9 days","8 days"],"answer":3,"explanation":"Total = 60 man-hours. At 7.5 hours a day: 60 ÷ 7.5 = 8 days.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-time-work-81","question":"12 carpenters working 8 hours a day make 360 chairs in 15 days. How many days will 16 carpenters working 9 hours a day take to make 540 chairs?","options":["20 days","12 days","15 days","18 days"],"answer":2,"explanation":"Each chair takes 12 × 8 × 15/360 = 4 carpenter-hours. 540 chairs need 2,160 hours; at 16 × 9 = 144 hours a day, that is 15 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-82","question":"A can finish a job in 10 days, and B is 25% more efficient than A. How long will B take alone?","options":["7.5 days","8 days","12.5 days","8.5 days"],"answer":1,"explanation":"Time ∝ 1/efficiency: 10 ÷ 1.25 = 8 days. Cutting 25% off 10 days (7.5) is the trap.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-83","question":"A tap fills 3/4 of a tank in 12 minutes. How much longer will it take to fill the rest?","options":["4 minutes","3 minutes","9 minutes","16 minutes"],"answer":0,"explanation":"1/4 of the tank takes 12/3 = 4 minutes.","difficulty":"moderate","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-time-work-84","question":"Typist A types 36 pages in 3 hours and typist B types 45 pages in 5 hours. Working together, how long will they take to type 189 pages?","options":["9 hours","8 hours","10.5 hours","7 hours"],"answer":0,"explanation":"A types 12 pages an hour and B 9. Together 21 an hour: 189 ÷ 21 = 9 hours.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-time-work-85","question":"A tailor stitches 8 shirts a day and his helper 5. For an order of 146 shirts, the tailor works alone for the first 2 days and then the helper joins him. In how many days is the order completed?","options":["11 days","13 days","10 days","12 days"],"answer":3,"explanation":"In 2 days the tailor makes 16 shirts. The remaining 130 at 13 a day take 10 days. Total = 12 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-86","question":"A can do a job in 20 days and B in 30 days. They work together for 4 days. What fraction of the job is left?","options":["1/3","1/2","2/3","3/5"],"answer":2,"explanation":"Together they do 1/12 a day, so 4/12 = 1/3 in 4 days. Two-thirds is left.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-87","question":"A can lay 1 km of pipeline in 6 days and B in 9 days. Working together, how long will they take to lay 2.5 km?","options":["7.5 days","9 days","10 days","8 days"],"answer":1,"explanation":"Together: 1/6 + 1/9 = 5/18 km a day. 2.5 ÷ 5/18 = 9 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-88","question":"6 robots pack 1,800 boxes in 5 hours. How many boxes will 8 robots pack in 7.5 hours?","options":["2,400","3,600","3,000","4,000"],"answer":1,"explanation":"Each robot packs 1,800/30 = 60 boxes an hour. 8 × 7.5 × 60 = 3,600 boxes.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-89","question":"3 pumps working 8 hours a day empty a tank in 2 days. How many hours a day must 4 pumps work to empty it in 1 day?","options":["12 hours","16 hours","10.67 hours","6 hours"],"answer":0,"explanation":"Pump-hours = 3 × 8 × 2 = 48. With 4 pumps in 1 day: 48 ÷ 4 = 12 hours.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-time-work-90","question":"30 men build a 120 m wall in 8 days. How many men are needed to build a 90 m wall in 5 days?","options":["30","45","32","36"],"answer":3,"explanation":"Each metre takes 30 × 8/120 = 2 man-days. 90 m need 180 man-days; in 5 days that is 36 men.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-91","question":"The efficiencies of A and B are in the ratio 5 : 3, and together they finish a job in 15 days. How long would A take alone?","options":["40 days","25 days","24 days","20 days"],"answer":2,"explanation":"Total work = (5 + 3) × 15 = 120 units. A alone = 120 ÷ 5 = 24 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-92","question":"A finishes 7/10 of a job in 14 days, and B finishes the rest in 9 days. How long would they take to do the whole job together?","options":["11.5 days","23 days","12 days","10 days"],"answer":2,"explanation":"A alone = 14 × 10/7 = 20 days; B does 3/10 in 9 days, so B alone = 30 days. Together 12 days.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-93","question":"12 typists type 360 pages in 5 hours. How many typists are needed to type 600 pages in 4 hours?","options":["20","25","24","30"],"answer":1,"explanation":"Each page takes 12 × 5/360 = 1/6 typist-hour. 600 pages need 100 typist-hours; in 4 hours that is 25 typists.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-time-work-94","question":"A is 40% more efficient than B, and C is 20% less efficient than B. If B alone takes 44 days to finish a job, how long will A and C take together?","options":["22 days","24 days","20 days","18 days"],"answer":2,"explanation":"Take B's rate as 1 unit: A = 1.4, C = 0.8, so A + C = 2.2 units. Time = 44 ÷ 2.2 = 20 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-95","question":"Pipe A alone fills a tank in 12 hours. When the tank is half full, pipe B, which can fill it alone in 6 hours, is also opened. How long does it take to fill the tank in all?","options":["9 hours","8 hours","6 hours","10 hours"],"answer":1,"explanation":"A fills the first half in 6 hours. Together they fill 1/12 + 1/6 = 1/4 an hour, so the second half takes 2 hours. Total 8 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-96","question":"Pipes A and B fill a tank in 20 and 25 minutes. A is opened first. After how many minutes should B be opened so that the tank is full exactly 15 minutes after A was opened?","options":["8.75 minutes","6.25 minutes","7.5 minutes","10 minutes"],"answer":0,"explanation":"In 15 minutes A fills 3/4. B must fill 1/4, which takes 25/4 = 6.25 minutes, so B is opened after 15 − 6.25 = 8.75 minutes.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-97","question":"40 workers can build a road in 60 days. After 15 days, 10 workers leave; after another 15 days, 20 new workers join. In how many days in all is the road finished?","options":["60 days","54 days","58 days","57 days"],"answer":3,"explanation":"Total = 2,400 worker-days. First 15 days: 600; next 15 days: 450. The remaining 1,350 at 50 workers take 27 days. Total = 57 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-98","question":"A can do a job in 18 days. B is 50% more efficient than A, and C is only half as efficient as A. How long will all three take together?","options":["7.2 days","5 days","8 days","6 days"],"answer":3,"explanation":"A = 18 days, B = 12 days, C = 36 days. With 36 units: 2 + 3 + 1 = 6 a day, so 6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-99","question":"A can do a job in 10 days and B in 15 days. They work together, but A takes a 2-day break in between. How many days does the job take?","options":["6 days","8 days","7.2 days","7 days"],"answer":2,"explanation":"If the job takes t days, A works t − 2 days: (t − 2)/10 + t/15 = 1 gives 3t − 6 + 2t = 30, so t = 7.2 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-100","question":"A job is done if A works 4 days and B works 6 days, or if A works 6 days and B works 3 days. How long would A take alone?","options":["12 days","8 days","10 days","9 days"],"answer":1,"explanation":"4a + 6b = 1 and 6a + 3b = 1. Doubling the second: 12a + 6b = 2. Subtracting the first: 8a = 1, so A takes 8 days (B takes 24).","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-101","question":"A is 60% more efficient than B, and together they finish a job in 12 days. How long would B take alone?","options":["31.2 days","19.2 days","30 days","24 days"],"answer":0,"explanation":"Rates A : B = 1.6 : 1, so together = 2.6 B-units. B alone takes 12 × 2.6 = 31.2 days.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-102","question":"A is 25% faster than B, and together they finish a job in 20 days. A works alone for 9 days and B then finishes the job. How many days does B work?","options":["33.75 days","36 days","30 days","31.25 days"],"answer":0,"explanation":"Together = 2.25 B-units, so B alone = 45 days and A alone = 36 days. A's 9 days do 1/4; B does 3/4 × 45 = 33.75 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-103","question":"A can do a job in 20 days and B in 30 days. Owing to a power cut, both work at only 80% of their usual efficiency. How long will they take together?","options":["12 days","14.4 days","9.6 days","15 days"],"answer":3,"explanation":"Normally they take 12 days together. At 80% efficiency the time becomes 12 ÷ 0.8 = 15 days (not 12 × 0.8).","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-104","question":"A can do a job in 18 days and B is 50% more efficient than A. They start together; after some days A leaves and B finishes the rest in 4 days. After how many days did A leave?","options":["4 days","6 days","4.8 days","5.2 days"],"answer":2,"explanation":"B alone = 12 days, so his last 4 days do 1/3. The other 2/3 was done together at 5/36 a day: (2/3) ÷ (5/36) = 4.8 days.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-105","question":"16 men working 9 hours a day dig a 72 m trench in 30 days. How many men working 12 hours a day can dig a 96 m trench in 24 days?","options":["24","20","18","16"],"answer":1,"explanation":"Each metre takes 16 × 9 × 30/72 = 60 man-hours. 96 m need 5,760 man-hours; 24 × 12 = 288 hours per man, so 20 men.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-106","question":"A and B are paid ₹2,400 for a job that A alone can do in 8 days and B alone in 12 days. They work together, but A leaves 2 days before the job is finished. If the pay is shared by work done, what does A get?","options":["₹1,440","₹1,200","₹960","₹1,000"],"answer":1,"explanation":"(t − 2)/8 + t/12 = 1 gives t = 6 days. A works 4 days and does 1/2 of the job, so he gets ₹1,200.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-time-work-107","question":"A does one-third of a job in 4 days. Then his efficiency rises by 50%. How many days does he take for the whole job?","options":["28/3 days","12 days","8 days","10 days"],"answer":0,"explanation":"His rate is 1/12 a day, rising to 1.5/12 = 1/8. The remaining 2/3 takes 16/3 days. Total = 4 + 16/3 = 28/3 days (9⅓).","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-108","question":"A can do a job in 12 days. With B's help he can do it in 8 days, and with C's help in 6 days. How long will B and C take together, without A?","options":["7 days","9 days","4.8 days","8 days"],"answer":3,"explanation":"B = 1/8 − 1/12 = 1/24 and C = 1/6 − 1/12 = 1/12. B + C = 3/24 = 1/8, so 8 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-109","question":"The efficiencies of A and B are in the ratio 4 : 3, and A finishes a job 6 days sooner than B. How long will they take together?","options":["12 days","21 days","72/7 days","10 days"],"answer":2,"explanation":"Times are in the ratio 3 : 4, a difference of 1 part = 6 days. So A = 18 and B = 24 days. Together: 18 × 24/42 = 72/7 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-110","question":"A group of men can finish a job in a certain number of days. With 6 more men it would be done 5 days earlier, and with 4 fewer men it would take 5 days longer. How many men are there?","options":["20","30","24","25"],"answer":2,"explanation":"nd = (n + 6)(d − 5) gives 6d − 5n = 30; nd = (n − 4)(d + 5) gives 5n − 4d = 20. Adding: 2d = 50, d = 25 and n = 24.","difficulty":"very-hard","source":"SSC CGL Tier 2 · SSC CPO"},
  {"id":"quant-time-work-111","question":"Ram does 1/3 of a job in 5 days. Shyam then does 2/5 of the remaining work in 4 days, and Mohan finishes the rest in 6 days. How long would all three take working together?","options":["6 days","5 days","4 days","7.5 days"],"answer":1,"explanation":"Ram alone = 15 days. Shyam does 4/15 in 4 days, so 15 days alone. Mohan does 2/5 in 6 days, also 15 days. Three at 1/15 each finish in 5 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-112","question":"A and B together can finish a job in 12 days. If A works for 3 days and B for 6 days, 7/20 of the job is done. How long would A take alone?","options":["20 days","30 days","15 days","24 days"],"answer":0,"explanation":"Working together for 6 days would do 6/12 = 1/2. A worked 3 of those days less, so 1/2 − 3a = 7/20, giving 3a = 3/20 and A alone = 20 days.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-113","question":"A contractor has 30 days to finish a project and employs 50 men working 8 hours a day. After 18 days only 2/5 of the work is done. How many more men must he hire, all working 10 hours a day from then on, to finish on time?","options":["30","50","25","40"],"answer":3,"explanation":"2/5 of the work = 50 × 8 × 18 = 7,200 man-hours, so 3/5 = 10,800. In 12 days × 10 hours = 120 hours per man, 90 men are needed: 40 more.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-114","question":"A takes 5 days more than B and 9 days more than C to do a job alone. A and B together take as long as C alone. How long does A take alone?","options":["10 days","6 days","12 days","15 days"],"answer":3,"explanation":"Let C = c, so A = c + 9 and B = c + 4. 1/(c + 9) + 1/(c + 4) = 1/c simplifies to c² = 36, so c = 6 and A = 15 days.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-time-work-115","question":"A is twice as efficient as B, and B is twice as efficient as C. A finishes a job 30 days sooner than C. How long will all three take together?","options":["7 days","10 days","40/7 days","20/3 days"],"answer":2,"explanation":"If A takes t days, C takes 4t: 3t = 30 gives t = 10. Rates 1/10 + 1/20 + 1/40 = 7/40, so 40/7 days (about 5.7).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-116","question":"Pipe A fills a tank in 12 hours and pipe B empties it in 18 hours. Starting with an empty tank, they are opened alternately for one hour each, A first. After how many hours is the tank first full?","options":["67 hours","72 hours","36 hours","66 hours"],"answer":0,"explanation":"Each 2-hour cycle adds 1/12 − 1/18 = 1/36. After 33 cycles (66 hours) the tank is 33/36 full, and A's next hour adds the last 3/36. Total 67 hours, not 72.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-117","question":"A works alone on day 1, A and B on day 2, A, B and C on day 3, and the pattern repeats. A, B and C alone take 30, 40 and 60 days. In how many days is the job done?","options":["20 days","15 days","17 days","18 days"],"answer":3,"explanation":"With 120 units: A = 4, B = 3, C = 2 per day. One 3-day cycle = 4 + 7 + 9 = 20 units, so 6 cycles = 120 units in exactly 18 days.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-time-work-118","question":"Pipes A and B fill a tank in 10 and 15 hours, and pipe C drains it. With all three open, the empty tank fills in 9 hours. How long would it take to fill the empty tank with only B and C open?","options":["18 hours","45 hours","90 hours","30 hours"],"answer":2,"explanation":"A + B = 1/6, so C drains 1/6 − 1/9 = 1/18 an hour. B − C = 1/15 − 1/18 = 1/90, so 90 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-119","question":"A and B together finish a job in t days. A alone would take 9 days more than t, and B alone 16 days more than t. What is t?","options":["12.5","12","25","10"],"answer":1,"explanation":"1/(t + 9) + 1/(t + 16) = 1/t simplifies to t² = 9 × 16 = 144, so t = 12. (The together-time is the geometric mean of the two extra times.)","difficulty":"very-hard","source":"SSC CGL Tier 2 · CAT-style"},
  {"id":"quant-time-work-120","question":"A can do a job in 60 days, and A and B together in 30 days. They work together for 20 days, then B is replaced by C, who is 50% more efficient than B. How many days does the whole job take?","options":["30 days","28 days","26 days","28.5 days"],"answer":1,"explanation":"B = 1/30 − 1/60 = 1/60, so C = 1/40. After 20 days, 2/3 is done. A + C = 1/60 + 1/40 = 1/24, so the last 1/3 takes 8 days. Total 28 days.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-121","question":"Machine X does a job in 6 hours and costs ₹400 an hour to run; machine Y does it in 9 hours at ₹300 an hour. What does the job cost if both machines work on it together?","options":["₹2,520","₹2,400","₹2,700","₹2,550"],"answer":0,"explanation":"Together they take 6 × 9/15 = 3.6 hours. Cost = 3.6 × (400 + 300) = ₹2,520 — more than X alone (₹2,400).","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-time-work-122","question":"Ramesh can finish a job in 6 hours and Suresh in 12 hours. Ramesh starts at 9:00 am and Suresh joins him at 11:00 am. When is the job finished?","options":["1:20 pm","2:00 pm","12:40 pm","1:40 pm"],"answer":3,"explanation":"By 11 am Ramesh has done 1/3. Together they do 1/4 an hour, so 2/3 takes 8/3 hours = 2 h 40 min. Finish = 1:40 pm.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-time-work-123","question":"A can paint a wall in 8 hours and B in 12 hours. A starts; B joins after 2 hours, and A stops 1 hour before the job is finished. How long does the job take in all?","options":["6 hours","5.8 hours","6.2 hours","7 hours"],"answer":2,"explanation":"If it takes t hours, A works t − 1 and B works t − 2: (t − 1)/8 + (t − 2)/12 = 1 gives 3t − 3 + 2t − 4 = 24, so t = 6.2 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-124","question":"18 workers complete 3/5 of a job in 12 days. How many additional workers are needed to finish the rest of the job in 4 days?","options":["36","12","18","24"],"answer":2,"explanation":"The whole job = 18 × 12 × 5/3 = 360 worker-days, so 2/5 = 144 worker-days. In 4 days that needs 36 workers: 18 more.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-125","question":"A pipe fills a tank in 10 hours. When the tank is half full, a crack appears at the bottom that drains 1/30 of the tank every hour. How long does it take in all to fill the tank?","options":["15 hours","12.5 hours","10 hours","13 hours"],"answer":1,"explanation":"First half: 5 hours. Then the net rate is 1/10 − 1/30 = 1/15, so the second half takes 7.5 hours. Total 12.5 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-126","question":"A machine working at full efficiency would finish a job in 10 hours. It runs at full efficiency for the first 4 hours, after which its efficiency drops to 80%. How long does the job take?","options":["11.5 hours","12.5 hours","11 hours","12 hours"],"answer":0,"explanation":"In 4 hours it does 40%. The remaining 60% at 8% an hour takes 7.5 hours. Total = 11.5 hours.","difficulty":"very-hard","source":"SSC CGL · RRB JE"},
  {"id":"quant-time-work-127","question":"A can do a job in 16 days and B in 12 days. With C's help they finish it in 4 days. If ₹4,800 is paid for the job and shared by work done, what is C's share?","options":["₹1,200","₹1,600","₹1,500","₹2,000"],"answer":3,"explanation":"In 4 days A does 1/4 and B does 1/3, so C does 1 − 1/4 − 1/3 = 5/12. C's share = 5/12 × 4,800 = ₹2,000.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-time-work-128","question":"A is paid ₹300 a day and finishes a job in 10 days; B is paid ₹200 a day and finishes it in 15 days. Which way of getting the job done costs least?","options":["A alone","B alone","A and B together","All three ways cost the same"],"answer":3,"explanation":"A alone: 10 × 300 = ₹3,000. B alone: 15 × 200 = ₹3,000. Together they take 6 days at ₹500 a day = ₹3,000. Each man's cost per job is the same, so every option costs ₹3,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-time-work-129","question":"20 men can finish a project in 30 days. After training, every worker becomes 10% more efficient. What is the least number of trained men that can finish the project in 24 days?","options":["22","25","23","21"],"answer":2,"explanation":"Work = 600 man-days at the old rate. In 24 days at 1.1 each, n × 26.4 ≥ 600 gives n ≥ 22.7. So 23 men are needed; 22 would fall short.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-130","question":"Pipe A fills a tank in 6 hours. Two hours after A is opened, an outlet pipe B is opened by mistake, and the tank becomes full 6 hours after that. How long would B alone take to empty the full tank?","options":["12 hours","18 hours","24 hours","9 hours"],"answer":1,"explanation":"A runs for 8 hours and supplies 8/6 = 4/3 of a tank. So B drained 1/3 of a tank in 6 hours, i.e. a full tank in 18 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-131","question":"A completes 2/7 of a job in 8 days. How long will he take for the whole job?","options":["16 days","24 days","56 days","28 days"],"answer":3,"explanation":"1/7 of the job takes 4 days, so the whole job takes 28 days.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-time-work-132","question":"A can do a job in 25 days and B in 20 days. A works for 5 days and leaves. How long does B take to finish the rest?","options":["15 days","20 days","16 days","12 days"],"answer":2,"explanation":"A does 1/5 in 5 days, leaving 4/5, which B does in 4/5 × 20 = 16 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-time-work-133","question":"Pipe A fills 1/3 of a tank in 10 minutes and pipe B fills 1/4 of it in 15 minutes. How long will both together take to fill the tank?","options":["25 minutes","20 minutes","12.5 minutes","18 minutes"],"answer":1,"explanation":"A alone = 30 min, B alone = 60 min. Together 30 × 60/90 = 20 minutes.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-134","question":"Pipes A and B fill a tank in 24 and 32 minutes. Both are opened together. After how many minutes should A be closed so that the tank is full in 18 minutes?","options":["10.5 minutes","8 minutes","12 minutes","13.5 minutes"],"answer":0,"explanation":"B runs all 18 minutes and fills 9/16. A must fill 7/16, which takes 7/16 × 24 = 10.5 minutes.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-time-work-135","question":"Pump A can empty a full pond in 12 hours and pump B in 15 hours. Rain inflow alone would fill the pond in 20 hours. With both pumps running in the rain, how long does it take to empty the full pond?","options":["10 hours","6.67 hours","15 hours","12 hours"],"answer":0,"explanation":"Net rate = 1/12 + 1/15 − 1/20 = (5 + 4 − 3)/60 = 1/10, so 10 hours.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-136","question":"A does 20% less work than B each day. Together they finish a job in 16 days. How long would B take alone?","options":["36 days","32 days","25.6 days","28.8 days"],"answer":3,"explanation":"A = 0.8 of B's rate, so together = 1.8 B-units. B alone = 16 × 1.8 = 28.8 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-137","question":"A patch of water hyacinth doubles its area every day and covers a whole lake at the end of day 10. At the end of which day was half the lake covered?","options":["Day 5","Day 8","Day 9","Day 7"],"answer":2,"explanation":"The area doubles each day, so the day before the lake is full it is exactly half covered: day 9. Halving the time (day 5) treats the growth as steady.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-time-work-138","question":"A, B and C can do a job alone in 10, 15 and 30 days. A and B work together throughout, and C joins them only for the last 2 days. How long does the job take?","options":["6 days","5.6 days","5 days","5.2 days"],"answer":1,"explanation":"A + B do 1/6 a day, and C adds 2/30 = 1/15 in total. So t/6 = 14/15 and t = 5.6 days.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-139","question":"A is paid ₹450 a day and can finish a job in 12 days; B is paid ₹300 a day and needs 20 days. Which of them is cheaper for the job, and by how much?","options":["B, by ₹600","A, by ₹600","A, by ₹150","Both cost the same"],"answer":1,"explanation":"A costs 12 × 450 = ₹5,400 and B costs 20 × 300 = ₹6,000. A is cheaper by ₹600 despite the higher daily wage.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"quant-time-work-140","question":"An inlet fills a tank in 2 hours and an outlet empties it in 3 hours. The inlet is opened alone, and the outlet is opened too after 1 hour. How long does the tank take to fill in all?","options":["4 hours","3 hours","6 hours","5 hours"],"answer":0,"explanation":"After 1 hour the tank is half full. The net rate is 1/2 − 1/3 = 1/6, so the other half takes 3 hours. Total 4 hours.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-time-work-141","question":"One worker makes 12 toys in 3 hours and another makes 10 toys in 2 hours. Working together 6 hours a day, in how many days will they make 324 toys?","options":["9 days","5 days","7 days","6 days"],"answer":3,"explanation":"Rates: 4 and 5 toys an hour, 9 together, so 54 toys a day. 324 ÷ 54 = 6 days.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-time-work-142","question":"3 men or 6 boys can do a job in 20 days. How long will 2 men and 4 boys take?","options":["20 days","10 days","15 days","12 days"],"answer":2,"explanation":"1 man = 2 boys, so 2 men + 4 boys = 8 boys. 6 boys take 20 days, so 8 boys take 20 × 6/8 = 15 days.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
];

